function scrollToY(e){window.scrollTo({top:e,behavior:"smooth"})}window.addEventListener("load",function(){let t=document.querySelector(".page-header"),n=document.querySelector(".promo__img");scrollToY(0),window.addEventListener("scroll",function(e){72<window.pageYOffset?t.classList.add("page-header__scroll"):t.classList.remove("page-header__scroll");var o=window.innerHeight;n.getBoundingClientRect().top<o-100&&(n.style.opacity="1",n.style.transform="translateX(0)")})});